const items = $input.all();
const p = (items && items[0] && items[0].json) ? items[0].json : {};
let data = p.body || p;
if (typeof data === 'string') { data = JSON.parse(data); }
if (!data || typeof data !== 'object') { data = {}; }
const obj = String(data.object || '');
const channel = obj === 'instagram' ? 'instagram' : 'facebook';
return [{ json: { channel: channel, payload: data } }];

const d = $input.first().json;
const payload = d.payload || d;
const store = $getWorkflowStaticData('global');
const ttlMs = 24 * 60 * 60 * 1000;
const now = Date.now();

if (!store.socialDedupe24h || typeof store.socialDedupe24h !== 'object') {
  store.socialDedupe24h = {};
}
const map = store.socialDedupe24h;
for (const [key, timestamp] of Object.entries(map)) {
  if (typeof timestamp !== 'number' || now - timestamp >= ttlMs) delete map[key];
}

const data = typeof payload === 'string' ? JSON.parse(payload) : (payload || {});
const object = String(data.object || d.channel || 'unknown');
const entries = Array.isArray(data.entry) ? data.entry : [];
let field = '';
let value = {};
for (const entry of entries) {
  for (const change of (Array.isArray(entry && entry.changes) ? entry.changes : [])) {
    const currentField = String(change.field || '');
    const currentValue = change.value || {};
    const commentLike = currentField === 'comments' ||
      (currentField === 'feed' && (currentValue.item === 'comment' || currentValue.comment_id));
    if (commentLike) {
      field = currentField;
      value = currentValue;
      break;
    }
  }
  if (field) break;
}

const commentLike = Boolean(field);
const text = String(value.text ?? value.message ?? '').slice(0, 2000);
const low = text.toLowerCase();
const hasKeyword = low.includes('link') || low.includes('enlace');
const from = value.from || {};
const userId = String(from.id || '');
const postId = object === 'instagram'
  ? String((value.media && value.media.id) || value.media_id || '')
  : String(value.post_id || (value.post && value.post.id) || '');
const eventId = String(value.comment_id || value.id || '');
const selfIds = new Set(['17841431723301731', '1348081288382156']);

if (!commentLike || !hasKeyword) {
  return [{ json: { ...d, duplicate: false, dedupe: 'skip', dedupeKey: '', eventId, dedupeReason: commentLike ? 'no-keyword' : 'not-a-comment-event' } }];
}
if (selfIds.has(userId)) {
  return [{ json: { ...d, duplicate: false, dedupe: 'skip', dedupeKey: '', eventId, dedupeReason: 'self-account' } }];
}
if (!userId || !postId) {
  return [{ json: { ...d, duplicate: true, dedupe: 'blocked', dedupeKey: '', eventId, dedupeReason: 'missing-user-or-post-id' } }];
}

const key = object + ':' + userId + ':' + postId;
const previous = map[key];
const duplicate = typeof previous === 'number' && now - previous < ttlMs;
if (!duplicate) map[key] = now;

return [{ json: {
  ...d,
  eventId,
  duplicate,
  dedupe: duplicate ? 'duplicate' : 'new',
  dedupeKey: key,
  dedupeReason: duplicate ? 'seen-within-24h' : 'not-seen-in-24h'
} }];

